INSERT INTO `tb_job` VALUES
(1,'2023-05-01 05:20:47',28,1,'2023-06-10 11:19:18',28,'IT Head','IT Head\n\nJob Summary:\n\nThe IT Head is responsible for leading the IT department and overseeing all IT operations. This position will be responsible for developing and implementing IT strategies, managing IT staff, and ensuring the security and reliability of the organizations IT systems.\n\nResponsibilities:\n\n Develop and implement IT strategies and plans that align with the organizations business objectives.\n Manage and oversee the IT department, including hiring, training, and evaluating staff.\n Ensure the security and reliability of the organizations IT systems.\n Monitor and analyze IT performance and recommend improvements.\n Research and evaluate new technologies and make recommendations for implementation.\n Develop and maintain IT policies and procedures.\n Manage IT budgets and ensure cost-effectiveness.\n Liaise with vendors and other stakeholders to ensure the smooth running of IT operations.\n Provide technical support and troubleshooting for IT systems.\n\nQualifications:\n\n Bachelors degree in Computer Science, Information Technology, or a related field.\n 5+ years of experience in IT management.\n Knowledge of IT systems, networks, and security protocols.\n Excellent problem-solving and communication skills.\n Ability to work independently and manage multiple projects.\n Strong leadership and organizational skills.','active','9J4B2',1,'assigned','Available, HR Interview, Hiring Manager Interview, Technical Test, Offer, Onboard'),
(2,'2023-05-01 05:20:57',28,1,'2023-06-10 11:23:20',28,'Java Lead','\n\nJob Title: Java Lead\n\nLocation: Remote\n\nJob Summary:\n\nWe are looking for an experienced Java Lead to join our team. The Java Lead will be responsible for leading the development of Java-based applications and providing technical guidance to the development team. The ideal candidate will have a strong background in Java development and a passion for developing high-quality software.\n\nResponsibilities:\n\n Lead the development of Java-based applications, ensuring that all code is written to the highest standards.\n\n Provide technical guidance and mentorship to the development team.\n\n Design and implement efficient and reliable software solutions.\n\n Troubleshoot and debug software issues.\n\n Monitor and optimize application performance.\n\n Ensure that all software is developed in accordance with industry best practices.\n\n Stay up-to-date with the latest technologies and trends in the Java development space.\n\nRequirements:\n\n Bachelors degree in Computer Science or related field.\n\n 5+ years of experience in Java development.\n\n Expertise in object-oriented programming and design patterns.\n\n Experience with web services and REST APIs.\n\n Knowledge of databases and SQL.\n\n Excellent problem-solving and communication skills.\n\n Ability to work independently and as part of a team.','active','YFRJZ',1,'assigned','Available, HR Interview, Hiring Manager Interview, Technical Test, Offer, Exclude, Onboard'),
(3,'2023-05-01 05:21:04',28,1,'2023-05-14 11:11:45',28,'IOS Lead','\n\nIOS Lead\n\nJob Summary:\n\nWe are looking for an experienced IOS Lead to join our team and lead the development of our IOS applications. The IOS Lead will be responsible for developing, testing, and deploying IOS applications, as well as managing the team of IOS developers.\n\nResponsibilities:\n\n Develop, test, and deploy IOS applications.\n\n Manage the team of IOS developers.\n\n Monitor and maintain the performance of IOS applications.\n\n Troubleshoot and resolve any issues with IOS applications.\n\n Ensure that all IOS applications are up to date with the latest technologies.\n\n Collaborate with other teams to ensure that IOS applications are integrated with other systems.\n\n Provide technical guidance and support to the IOS development team.\n\n Stay up to date with the latest IOS technologies and trends.\n\nRequirements:\n\n Bachelors degree in Computer Science, Information Technology, or related field.\n\n 5+ years of experience developing IOS applications.\n\n Expert knowledge of IOS development tools and frameworks.\n\n Experience managing and leading a team of IOS developers.\n\n Excellent problem-solving and communication skills.\n\n Ability to work independently and as part of a team.','active','KJ00D',1,'assigned','Available, HR Interview, Hiring Manager Interview, Technical Test, Offer, Exclude'),
(4,'2023-05-01 05:21:10',28,1,'2023-05-14 11:11:47',28,'Android Lead','\n\nAndroid Lead\n\nJob Summary:\n\nWe are looking for an experienced Android Lead to join our team and lead the development of our Android applications. The Android Lead will be responsible for designing, developing, and maintaining our Android applications, as well as providing technical guidance and support to the Android development team.\n\nResponsibilities:\n\n Design, develop, and maintain Android applications.\n\n Lead the Android development team and provide technical guidance and support.\n\n Collaborate with other teams to ensure successful integration of Android applications with other systems.\n\n Monitor and optimize application performance.\n\n Troubleshoot and debug application issues.\n\n Develop and maintain documentation related to Android applications.\n\n Stay up-to-date with the latest Android technologies and trends.\n\nRequirements:\n\n Bachelors degree in Computer Science, Software Engineering, or related field.\n\n 5+ years of experience developing Android applications.\n\n Expert knowledge of Java, Kotlin, and Android SDK.\n\n Experience with Android Studio, Gradle, and other development tools.\n\n Knowledge of RESTful APIs and web services.\n\n Excellent problem-solving and communication skills.\n\n Ability to work independently and as part of a team.','active','G19QI',1,'assigned','Available, HR Interview, Hiring Manager Interview, Technical Test, Offer, Exclude'),
(5,'2023-05-01 09:54:25',28,1,'2023-05-14 11:11:48',28,'Java Programmer','Job Title: Java Programmer\n\nJob Summary:\n\nWe are looking for an experienced Java Programmer to join our team. The successful candidate will be responsible for developing, testing, and maintaining software applications using the Java programming language. The ideal candidate should have a strong understanding of object-oriented programming principles and be able to work independently and collaboratively.\n\nResponsibilities:\n\n Develop, test, and maintain software applications using the Java programming language\n Design and implement software solutions to meet customer requirements\n Troubleshoot and debug software applications\n Create and maintain technical documentation\n Collaborate with other developers and stakeholders to ensure successful project completion\n Stay up-to-date with the latest technologies and trends\n\nRequirements:\n Bachelors degree in Computer Science or related field\n 5+ years of experience in software development\n Expertise in Java programming language\n Knowledge of object-oriented programming principles\n Experience with web development frameworks such as Spring and Hibernate\n Familiarity with databases such as MySQL and Oracle\n Excellent problem-solving and communication skills\n Ability to work independently and collaboratively','active','INYXD',1,'assigned','Available, HR Interview, Hiring Manager Interview, Technical Test, Offer, Exclude'),
(6,'2023-05-13 09:27:06',28,1,'2023-05-13 09:27:35',28,'Song Writer','Job Title: Song Writer\n\nJob Summary:\n\nWe are looking for an experienced and creative Song Writer to join our team. The Song Writer will be responsible for writing original music and lyrics for our projects. The ideal candidate should have a strong understanding of music theory and be able to create unique and engaging songs.\n\nResponsibilities:\n\n Write original music and lyrics for our projects\n\n Collaborate with other songwriters and producers to create unique and engaging songs\n\n Research and develop new musical ideas\n\n Record and produce demos of songs\n\n Participate in songwriting sessions\n\n Ensure all songs are completed on time and within budget\n\n Maintain a high level of creativity and quality\n\n Stay up to date with industry trends\n\nRequirements:\n\n Bachelors degree in Music or related field\n\n Proven experience as a songwriter\n\n Excellent knowledge of music theory\n\n Ability to work independently and collaboratively\n\n Excellent communication and interpersonal skills\n\n Proficient in music production software\n\n Ability to work under pressure and meet deadlines\n\n Passion for music and creativity','active','D0LE7',NULL,NULL,'Scheduling Interview, HR Interview, Hiring Manager Interview, Technical Test, Offer'),
(7,'2023-05-13 10:03:03',28,1,'2023-05-14 05:25:08',28,'Chef','\n\nJob Title: Chef\n\nJob Summary:\n\nWe are looking for an experienced and creative Chef to join our team. The Chef will be responsible for creating and preparing delicious meals for our customers. The Chef will be expected to have a strong knowledge of food preparation and presentation techniques, as well as a passion for creating unique and flavorful dishes.\n\nResponsibilities:\n\n Create and prepare delicious meals for customers\n Develop and maintain menus that are creative and appealing\n Ensure that all food is prepared in accordance with health and safety regulations\n Monitor food inventory and order supplies as needed\n Train and supervise kitchen staff\n Maintain a clean and organized kitchen\n Monitor food costs and portion control\n Develop and implement new recipes\n\nQualifications:\n\n Proven experience as a Chef\n Knowledge of food preparation and presentation techniques\n Ability to work in a fast-paced environment\n Excellent organizational and time management skills\n Ability to work independently and as part of a team\n Knowledge of health and safety regulations\n Culinary school degree or equivalent experience','active','13QR0',NULL,NULL,'Scheduling Interview, HR Interview, Hiring Manager Interview, Technical Test, Offer'),
(8,'2023-05-15 07:24:56',28,1,'2023-06-10 16:50:57',28,'Sales Associate','Sales Associate\n\nJob Summary:\n\nWe are looking for an experienced and motivated Sales Associate to join our team. The Sales Associate will be responsible for providing excellent customer service, building relationships with customers, and helping to drive sales. The ideal candidate will have excellent communication and interpersonal skills, be highly organized, and have a strong understanding of sales principles.\n\nResponsibilities:\n\n Greet customers and provide excellent customer service\n Assist customers in selecting products that meet their needs\n Answer customer questions and provide product information\n Process sales transactions accurately and efficiently\n Maintain a clean and organized sales floor\n Assist in maintaining inventory levels\n Assist in merchandising and display setup\n Participate in store promotions and events\n Follow all company policies and procedures\n\nRequirements:\n\n High school diploma or equivalent\n Previous retail sales experience preferred\n Excellent communication and interpersonal skills\n Ability to work independently and as part of a team\n Ability to stand for long periods of time\n Ability to lift up to 25 lbs.\n\nIf you are interested in this position, please submit your resume and cover letter for consideration. We look forward to hearing from you!','active','90N8D',12,'assigned','Scheduling Interview, HR Interview, Hiring Manager Interview, Technical Test, Offer, Onboard');
/*!40000 ALTER TABLE `tb_job` ENABLE KEYS */;
