(7,'2023-05-13 10:56:23',28,1,'2023-05-19 13:21:51',28,'Benny  Benyamin','Benny','Benyamin','','','+6283806046348,021 - 8643988,770813050587','','benniebenz@gmail.com','1978-08-01',NULL,NULL,NULL,NULL,NULL,'Jl. Bukit Golf Riverside cluster Arcadia residence A10 / 26 Cimanggis Depok , West of Java.',NULL,NULL,NULL,NULL,'','Indonesian,English',NULL,'',18,NULL,'[{\"id\":22568977,\"organization\":\"TK St. Angela Bandung\",\"accreditation\":{\"inputStr\":\"\",\"matchStr\":\"\"},\"dates\":{\"startDate\":\"1983-01-01\",\"completionDate\":\"1984-01-01\",\"isCurrent\":false,\"rawText\":\"1983-1984\"}},{\"id\":22568978,\"organization\":\"SD St. Angela Bandung\",\"accreditation\":{\"inputStr\":\"\",\"matchStr\":\"\"},\"dates\":{\"startDate\":\"1984-01-01\",\"completionDate\":\"1990-01-01\",\"isCurrent\":false,\"rawText\":\"1984-1990\"}},{\"id\":22568979,\"organization\":\"Junior High School\",\"accreditation\":{\"inputStr\":\"\",\"matchStr\":\"\"},\"dates\":{\"startDate\":\"1990-01-01\",\"completionDate\":\"1993-01-01\",\"isCurrent\":false,\"rawText\":\"1990-1993\"}},{\"id\":22568980,\"organization\":\"High School\",\"accreditation\":{\"inputStr\":\"\",\"matchStr\":\"\"},\"dates\":{\"startDate\":\"1993-01-01\",\"completionDate\":\"1996-01-01\",\"isCurrent\":false,\"rawText\":\"1993-1996\"}},{\"id\":22568981,\"organization\":\"STT Telkom Bandung\",\"accreditation\":{\"education\":\"Bachelor Degree\",\"educationLevel\":\"bachelors\",\"inputStr\":\"Bachelor Degree\",\"matchStr\":\"\"},\"dates\":{\"completionDate\":\"2004-01-01\",\"isCurrent\":false,\"rawText\":\"January 2004\"}}]','Project Manager | Project Engineer',NULL,'[{\"id\":39505819,\"jobTitle\":\"Site Engineer / Project Engineer\",\"organization\":\"Huawei Tech Investment, PT.\",\"dates\":{\"startDate\":\"2012-04-10\",\"endDate\":\"2023-05-13\",\"monthsInPosition\":133,\"isCurrent\":true,\"rawText\":\"(April, 10th 2012 – Present)\"},\"jobDescription\":\"Banten Area – Indonesia. (April, 10th 2012 – Present) 3 months contract extendable. Scope of works : \\n-Coordination and Monitoring TI Sub Contractor Activity for Material On Site (MOS), Installation BTS 2G/3G and MW, Integration until Acceptance Test (ATP) done. \\n-Regular Monitoring and reporting regarding Monthly Target for TI Subconts, Access Permit will be expired, Access Issue and TI activity as required base on contract. \\n-Involved for Troubleshooting activity if problem appeared. \\n-Supervise installation and did commissioning for 2G and 3G huawei BTS DBS 3900A, BTS 3900 indoor and outdoor. \\n-Process Escalation if any problem appeared on site like Power Issue, CME not RFI, Stolen Issue, cross feeder, Faulty Material and communicate well with others department. \\n-Migration Microwave to Hybrid Networking (Native E1 and IP) and IP Networking for Axis AMBER Project, Jakarta, Indonesia. \\n-Supervise and control sub contractors to do installation to make sure meet the customer requirements. \\n-Conduct ATP 2G, 3G, and MW onsite with subconts and customers. \\n-Communicate with other departments and vendors (Customer Service, Marketing, Sales, Implementation, Operation, and other) for network quality improvement initiatives or problem coordination and control. \\n-Conduct for produce daily, weekly, monthly and other reporting to Management about network quality level. \",\"occupation\":{\"jobTitle\":\"Site Engineer / Project Engineer\",\"jobTitleNormalized\":\"Site Project Engineer\",\"managementLevel\":\"Low\"}},{\"id\":39505820,\"jobTitle\":\"\",\"organization\":\"Surya Energi Indotama, PT.\",\"jobDescription\":\"(LEN subsidiaries) \",\"occupation\":{\"jobTitle\":\"\"}},{\"id\":39505821,\"jobTitle\":\"\",\"organization\":\"Xair Technologies, PT.\",\"jobDescription\":\"Supplier Services) \",\"occupation\":{\"jobTitle\":\"\"}},{\"id\":39505822,\"jobTitle\":\"\",\"organization\":\"TUNAS GRAHA SERVINDO\",\"location\":{\"formatted\":\"117 W 9th St, Coffeyville, KS 67337, USA\",\"streetNumber\":\"117\",\"street\":\"West 9th Street\",\"city\":\"Coffeyville\",\"postalCode\":\"67337\",\"state\":\"Kansas\",\"country\":\"United States\",\"rawInput\":\"PT\",\"countryCode\":\"US\",\"latitude\":37.0349141,\"longitude\":-95.616542},\"jobDescription\":\"\",\"occupation\":{\"jobTitle\":\"\"}},{\"id\":39505823,\"jobTitle\":\"Project Engineer for renewable\",\"jobDescription\":\"Scope of works : \\n•Site Survey and PhotoVoltaic system Simulation \\n-Responsible for making Site Survey for Solar Cell Implementation \\n-Collected some parameter for solarcell design such sun radiation (W/m2) using Solarimeter, Wind (m/s) and Temperature (°C) using Anemometer. \\n-Measurement capacity load needed for Solar Cell like load ampere and load voltage. \\n-Designed engineering using PVsyst 5 as simulation for solar cell placement and measurement. \\n-Conduct for fabrication fix system equipment from designed PV module, junction box, MCB needed, arrester, Outback SCC, inverter DC to AC, configure NMS via sms and designed battery backup system. \\n•Packaging and Delivery \\n-Conduct for material packaging and delivery using local expedition. \\n-Monitoring delivery material with local expedition until received by installation team. \\n•Supervise installation, commissioning, integration and acceptance test \\n-Checking site installation regarding Civil Work, Mechanical and Electrical activities. \\n-Testing and commissioning Solar Charge Controller with PV module. \\n-Integration Existing equipment by connecting DC voltage from SCC to rectifier existing. \\n-Acceptance test with customer after integration finished. \",\"occupation\":{\"jobTitle\":\"Project Engineer for renewable\",\"jobTitleNormalized\":\"Renewable Energy Engineer\",\"classification\":{\"socCode\":2127,\"title\":\"Engineering project managers and project engineers\",\"minorGroup\":\"Engineering Professionals\",\"subMajorGroup\":\"SCIENCE, RESEARCH, ENGINEERING AND TECHNOLOGY PROFESSIONALS\",\"majorGroup\":\"PROFESSIONAL OCCUPATIONS\"},\"managementLevel\":\"Low\"}},{\"id\":39505824,\"jobTitle\":\"Assistant PM for Modernization\",\"dates\":{\"startDate\":\"2011-04-01\",\"endDate\":\"2011-07-01\",\"monthsInPosition\":3,\"isCurrent\":false,\"rawText\":\"( April 1 st 2011 – July 2011)\"},\"jobDescription\":\"Interface Telkomsel Sumbagteng Area. ( April 1 st 2011 – July 2011) Scope of works : \\n•BSC Flexi3i and TCSM3i Installation Supervisor \\n-Check Installation of BSC Flexi3i and TCSM3i according to Technical Site Survey Report (TSSR). \\n-Support testing E1 transmission for Re-homing and Re-parenting activity. \\n-Conduct for Ater/Abis and A if interface installation and x-connection before Re-homing and Re-parenting. \\n-Conduct for BTS 2G Flexi Multi Radio (FMR) DCS installation, hotswap and commissioning activity. \\n-Support for Transmission Survey and Reporting E1 availability to Transmission Planning Division. \\n-Routine checking material in warehouse Padang for make sure database valid. \\n-Arrange team subcontractor for Material on Site and starting installation activity at the site. \\n•Transmission Preparation for Modernization Gemini Project Plan \\n-Coordination with transmission Planning/TNP for execution x connection as customer plan for TRX upgrade, new or collocated FMR, change drop insert to star configuration, etc \\n-Made Transmission Preparation for Re-homing activity which starting middle of the night. \\n-Coordination with Tsel Operator for starting Re-homing activity from Siemens BSC HC120 to Flexi BSC3i \\n-Execution moving transmission from existing Siemens Slim Rack to new FBSC slim rack during rehoming. \",\"occupation\":{\"jobTitle\":\"Assistant PM for Modernization\",\"jobTitleNormalized\":\"Modernization Superintendent\",\"classification\":{\"socCode\":5330,\"title\":\"Construction and building trades supervisors\",\"minorGroup\":\"Construction and Building Trades Supervisors\",\"subMajorGroup\":\"SKILLED CONSTRUCTION AND BUILDING TRADES\",\"majorGroup\":\"SKILLED TRADES OCCUPATIONS\"},\"managementLevel\":\"Low\"}},{\"id\":39505825,\"jobTitle\":\"Coordinator of Manage Service\",\"organization\":\"SIEMENS INDONESIA\",\"location\":{\"formatted\":\"117 W 9th St, Coffeyville, KS 67337, USA\",\"streetNumber\":\"117\",\"street\":\"West 9th Street\",\"city\":\"Coffeyville\",\"postalCode\":\"67337\",\"state\":\"Kansas\",\"country\":\"United States\",\"rawInput\":\"PT\",\"countryCode\":\"US\",\"latitude\":37.0349141,\"longitude\":-95.616542},\"dates\":{\"startDate\":\"2010-03-07\",\"endDate\":\"2011-03-07\",\"monthsInPosition\":12,\"isCurrent\":false,\"rawText\":\"( 7 March 2010 – 7 March 2011)\"},\"jobDescription\":\"•Huawei – AXIS NTS Manage Service Project for West Java Area. \\n-Received Trouble Ticket from NOC Axis then escalated the problem to cluster engineer for performed troubleshooting. Siemens Indonesia, PT Noviacom – Riyadh – KSA (www.noviacom.net) \",\"occupation\":{\"jobTitle\":\"Coordinator of Manage Service\",\"jobTitleNormalized\":\"Service Coordinator\"}},{\"id\":39505826,\"jobTitle\":\"I\\u0026 C (Installation \\u0026 Commissioning) Supervisor\",\"dates\":{\"startDate\":\"2006-06-01\",\"endDate\":\"2010-03-01\",\"monthsInPosition\":45,\"isCurrent\":false,\"rawText\":\"( June 2006 to March 2010)\"},\"jobDescription\":\"Hutchinson CAROENK POKPHAN Telecommunication /HCPT – SIEMENS Projects in Indonesia SIEMENS by consultant for Java and Bali region. ( June 2006 to March 2010) Scope of works : \\n•BTS SIEMENS BR241, BR82 Installation \\u0026 Commissioning Supervisor Check Installation of SIEMENS BTS for BR241, BR82 according to site binder. Arrange material request from the Warehouse for Installation. Power up BTS hardware and Commissioning BTS Software for 3 phase, setting PCM-B, LAPDL-A for star or multi drop depend on timeslot, Configuration Cell like DUVSWR, DULNA and FCU as well as semi rigid installed each sector, setting ENVA for external alarm like Mains Failure, OBL Failure and Arrester Failure and made necessary testing with NOC. Acceptance test (ATP) with Managed Service and fill up the binder for documentation like ATMN MW, BTS for signed Receive trouble Ticket from NOC/MS during Site not Accepted to troubleshoot (Bs288,Bs241,Service Rack, Network Problem) \\n-Conduct for commissioning software like default setting hardware IDU, Frequency TX and Rx, E1 capacity belongs to memory Key, IP address setting as DCN planning. \\n-Conduct for alignment and capture the result of RSL. \\n-Conduct for ATMN doc like Transmission Capture, interference test, BER Test, MW Inventory and report to Implementation Manager. \\n-Conduct also for receive trouble ticket from NOC and made necessary troubleshoot at the sites. \",\"occupation\":{\"jobTitle\":\"I\\u0026 C (Installation \\u0026 Commissioning) Supervisor\",\"jobTitleNormalized\":\"Commissioning Supervisor\",\"classification\":{\"socCode\":5330,\"title\":\"Construction and building trades supervisors\",\"minorGroup\":\"Construction and Building Trades Supervisors\",\"subMajorGroup\":\"SKILLED CONSTRUCTION AND BUILDING TRADES\",\"majorGroup\":\"SKILLED TRADES OCCUPATIONS\"},\"managementLevel\":\"Low\"}},{\"id\":39505827,\"jobTitle\":\"Ericsson RBS / Mini link Tester Engineer\",\"organization\":\"NoviaCom\",\"location\":{\"formatted\":\"Riyadh 11564, Saudi Arabia\",\"city\":\"Riyadh\",\"postalCode\":\"11564\",\"state\":\"Riyadh Province\",\"country\":\"Saudi Arabia\",\"rawInput\":\"Riyadh\",\"countryCode\":\"SA\",\"latitude\":24.7135517,\"longitude\":46.6752957},\"dates\":{\"startDate\":\"2005-11-10\",\"endDate\":\"2006-05-15\",\"monthsInPosition\":6,\"isCurrent\":false,\"rawText\":\"( 10th November 2005 – 15th May 2006)\"},\"jobDescription\":\"Scope of works : \\n•RBS 2000 family and Mini Link PDH Installation Supervisor \\n-Supervise the quality of Installation for RBS 2202 / 2206 system, Installation of Feeder Antennas, Distribution Box (DF) for External alarm connection, Check the position all of equipment according to the site binder (Rectifier, Transmission Rack, Batteries, Radio Base Station Cabinet, cable ladder), check every connection and also labels. \\n-Make Sweep test with ANRITSU Site master and collect data for VSWR \",\"occupation\":{\"jobTitle\":\"Ericsson RBS / Mini link Tester Engineer\"}},{\"id\":39505828,\"jobTitle\":\"\",\"organization\":\"PT. ERICSSON INDONESIA\",\"jobDescription\":\"\",\"occupation\":{\"jobTitle\":\"\"}},{\"id\":39505829,\"jobTitle\":\"Test Call Engineer\",\"organization\":\"MSC Ericsson\",\"dates\":{\"startDate\":\"2005-08-10\",\"endDate\":\"2005-10-30\",\"monthsInPosition\":3,\"isCurrent\":false,\"rawText\":\"( 10th August 2005 – 30th October 2005)\"},\"jobDescription\":\"Scope of works : 1. Test every Feature at APG40 MSC. 2. Monitoring DIP switch Transmission at MSC/BSC. \",\"occupation\":{\"jobTitle\":\"Test Call Engineer\",\"jobTitleNormalized\":\"Test Engineer\",\"classification\":{\"socCode\":8143,\"title\":\"Routine inspectors and testers\",\"minorGroup\":\"Assemblers and Routine Operatives\",\"subMajorGroup\":\"PROCESS, PLANT AND MACHINE OPERATIVES\",\"majorGroup\":\"PROCESS, PLANT AND MACHINE OPERATIVES\"},\"managementLevel\":\"Low\"}},{\"id\":39505830,\"jobTitle\":\"Site Survey Engineer\",\"dates\":{\"startDate\":\"2005-07-10\",\"endDate\":\"2005-08-09\",\"monthsInPosition\":1,\"isCurrent\":false,\"rawText\":\"( 10th July 2005 – 9th August 2005 )\"},\"jobDescription\":\"Scope of works : 1. Transmission LOS Survey for EXCELCOM Operator. 2. Do Path loss calculation after collect data survey and make report to \",\"occupation\":{\"jobTitle\":\"Site Survey Engineer\",\"jobTitleNormalized\":\"Survey Engineer\",\"classification\":{\"socCode\":5319,\"title\":\"Construction and building trades n.e.c.\",\"minorGroup\":\"Construction and Building Trades\",\"subMajorGroup\":\"SKILLED CONSTRUCTION AND BUILDING TRADES\",\"majorGroup\":\"SKILLED TRADES OCCUPATIONS\"},\"managementLevel\":\"Low\"}},{\"id\":39505831,\"jobTitle\":\"Operation and Maintenance (O \\u0026 M) Engineer(\",\"dates\":{\"startDate\":\"2005-05-02\",\"endDate\":\"2005-07-10\",\"monthsInPosition\":2,\"isCurrent\":false,\"rawText\":\"2nd May 2005 – 10th July 2005\"},\"jobDescription\":\"Scope of works : 1. Maintenance and Troubleshooting RBS and Mini Link under Ericsson O\\u0026M Division. 2. Clearing Alarm from BSC / MSC. 3. Updated reports day by day for status site in JABOTABEK Region to O\\u0026M Manager before continue for ATP. \",\"occupation\":{\"jobTitle\":\"Operation and Maintenance (O \\u0026 M) Engineer(\",\"jobTitleNormalized\":\"Operations and Maintenance Engineer\",\"managementLevel\":\"Low\"}},{\"id\":39505832,\"jobTitle\":\"Tester Engineer\",\"organization\":\"Single BSS Network PT. Ericsson Indonesia\",\"dates\":{\"startDate\":\"2004-08-01\",\"endDate\":\"2005-04-30\",\"monthsInPosition\":9,\"isCurrent\":false,\"rawText\":\"1 st August 2004 – 30th April 2005\"},\"jobDescription\":\"Scope of works : \\n•RBS (2202, 2206, 2207) and Mini Link Installation Supervisor \\n-Check Installation RBS and Mini-Link from the binder at the site. \\n-Supervisor materials at the site and check quality installation from Ericsson Subcontractor then report to Implementation Manager. \\n-Measurement VSWR, DTF and Return Loss from site master is required. \\n•RBS and Mini Link Pre-commissioning, Testing, and Commissioning \\n-After installation complete, use OMT for Create IDB RBS software, check status E1 Transmission (Stand Alone or Cascade) to BSC and preloading RBS if possible, if E1 re-use so doing that at Cut Over Night for Swap old BTS. \\n-Test Call and Handover with TEMS Pocket after BTS on air (Integration with BSC) and monitoring for one hour with OMT about CDU output power, ARFCN, Signal Quality, etc. Computer and Communication Laboratory \",\"occupation\":{\"jobTitle\":\"Tester Engineer\",\"jobTitleNormalized\":\"Software Engineer Tester\",\"classification\":{\"socCode\":2134,\"title\":\"Programmers and software development professionals \",\"minorGroup\":