or Methodology that were deployed: Microsoft Word, Microsoft Project, Microsoft Excel, C++, J2EE, Oracle Database, MySQL Database, SQL Developer, Toad for MySQL, Apache Tomcat, Oracle Weblogic, Oracle SOA Suite. \",\"occupation\":{\"jobTitle\":\"Technical Consultant\",\"jobTitleNormalized\":\"Technical Consultant\",\"classification\":{\"socCode\":2139,\"title\":\"Information technology professionals n.e.c.\",\"minorGroup\":\"Information Technology Professionals\",\"subMajorGroup\":\"SCIENCE, RESEARCH, ENGINEERING AND TECHNOLOGY PROFESSIONALS\",\"majorGroup\":\"PROFESSIONAL OCCUPATIONS\"},\"managementLevel\":\"Low\"}}]','[{\"id\":233007586,\"emsiId\":\"KS440W865GC4VRBW6LJP\",\"name\":\"SQL (Programming Language)\",\"lastUsed\":\"2021-03-01\",\"numberOfMonths\":122,\"type\":\"hard_skill\",\"sources\":[{\"section\":\"WorkExperience\",\"position\":1,\"workExperienceId\":39505870},{\"section\":\"WorkExperience\",\"position\":2,\"workExperienceId\":39505871},{\"section\":\"WorkExperience\",\"position\":3,\"workExperienceId\":39505872},{\"section\":\"Training/Certifications\"}]},{\"id\":233007587,\"emsiId\":\"KS1200C5XQWW78VQ5ZYL\",\"name\":\"PHP (Scripting Language)\",\"lastUsed\":\"2021-03-01\",\"numberOfMonths\":62,\"type\":\"hard_skill\",\"sources\":[{\"section\":\"WorkExperience\",\"position\":1,\"workExperienceId\":39505870},{\"section\":\"Training/Certifications\"}]},{\"id\":233007588,\"emsiId\":\"KSJF3PBD3995K6E0OF1Z\",\"name\":\"Kubernetes\",\"lastUsed\":\"2021-03-01\",\"numberOfMonths\":62,\"type\":\"hard_skill\",\"sources\":[{\"section\":\"WorkExperience\",\"position\":1,\"workExperienceId\":39505870}]},{\"id\":233007589,\"emsiId\":\"KS1261Z68KSKR1X31KS3\",\"name\":\"Machine Learning\",\"lastUsed\":\"2021-03-01\",\"numberOfMonths\":62,\"type\":\"hard_skill\",\"sources\":[{\"section\":\"WorkExperience\",\"position\":1,\"workExperienceId\":39505870}]},{\"id\":233007596,\"emsiId\":\"KS441S66KZY7LM20RKYN\",\"name\":\"Software Versioning\",\"lastUsed\":\"2021-03-01\"