ription\":\"Project based consultant on various projects from private and government owned company : PT Rajawali Berdikari Indonesia Attendance Application PT. Tiga Global Sejahtera Distribution Management System https://dms.id-trec.com PT Kustodian Sentral Efek Indonesia (KSEI) Revamp GUI for S-Invest Latest technology and/or Methodology that were deployed: Vaadin Angular \",\"occupation\":{\"jobTitle\":\"Founder - eCommerce Implementation Consultant\"}},{\"id\":39693488,\"jobTitle\":\"Senior Manager Development\",\"organization\":\"Alfamart Digital Business\",\"dates\":{\"startDate\":\"2016-01-01\",\"endDate\":\"2021-03-01\",\"monthsInPosition\":62,\"isCurrent\":false,\"rawText\":\"January 2016 – March 2021\"},\"jobDescription\":\"(direct report to VP of IT) January 2016 – March 2021 Managing and mentoring development team in all activities from assessment, pre development strategy, development phase, deployment rollout, and post deployment. Leading development team to delivery ecommerce microservices based applications for both frontend and backend. Technology and/or Methodology that were deployed: Ubuntu Desktop, Ubuntu Server, Centos, Microsoft Windows, Microsoft Project, Microsoft Power point, Microsoft Word, Php, J2EE, Oracle Service Bus, Oracle Database, PostgreSQL Database, MySQL Database, Magento Enterprise, SOLR, Java JAX-WS, Java JAX-RS, Google Web Toolkit, Apache Tomcat, Oracle Weblogic, Code Igniter, Bootstrap, SVN, JIRA, Confluence, Google Cloud Platform, Amazon Web Services, MongoDB, Redis, Kubernetes, Kafka, Confluent, Spring Boot, Machine Learning (Weka, Rapidminer). \",\"occupation\":{\"jobTitle\":\"Senior Manager Development\",\"jobTitleNormalized\":\"Development Manager\",\"classification\":{\"socCode\":2132,\"title\":\"IT managers\",\"minorGroup\":\"Information Technology Professionals\",\"subMajorGroup\":\"SCIENCE, RESEARCH, ENGINEERING AND TECHNOLOGY PROFESSIONALS\",\"majorGroup\":\"PROFESSIONAL OCCUPATIONS\"},\"managementLevel\":\"Mid\"}},{\"id\":39693489,\"jobTitle\":\"Senior Manager Backend Developer\",\"organization\":\"PT. XL Planet (elevenia.co.id)\",\"dates\":{\"startDate\":\"2014-01-01\",\"endDate\":\"2015-12-01\",\"monthsInPosition\":23,\"isCurrent\":false,\"rawText\":\"January 2014 - December 2015\"},\"jobDescription\":\"Having responsibilities for giving assessment of possibilities, options, and schedule for task and giving directions, strategies, and guidance to team for completing the task based on team load and team capacity. Technology and/or Methodology that were deployed: Microsoft Power point, Microsoft Word, J2EE, Oracle Database, SQL Developer, Apache Tomcat, Oracle Weblogic. \",\"occupation\":{\"jobTitle\":\"Senior Manager Backend Developer\",\"jobTitleNormalized\":\"Drupal Backend Developer\",\"classification\":{\"socCode\":2134,\"title\":\"Programmers and software development professionals \",\"minorGroup\":\"Information Technology Professionals\",\"subMajorGroup\":\"SCIENCE, RESEARCH, ENGINEERING AND TECHNOLOGY PROFESSIONALS\",\"majorGroup\":\"PROFESSIONAL OCCUPATIONS\"},\"managementLevel\":\"Low\"}},{\"id\":39693490,\"jobTitle\":\"Technical Consultant\",\"organization\":\"PT Mitra Integrasi Informatika\",\"dates\":{\"startDate\":\"2010-11-01\",\"endDate\":\"2013-12-01\",\"monthsInPosition\":37,\"isCurrent\":false,\"rawText\":\"November 2010 – December 2013\"},\"jobDescription\":\"Extending, design and deliver KPEI Middleware, as a backbone for KPEI day to day operational process. Design phase: Gathering requirement and coordinate with multiple application vendors to provide SOA design. Create Project Plan, High Level Requirement, Business Proposal, and Document Design. Deliver phase: In charge with weekly Progress Meeting to update user with the latest condition of project, also with risks and issues arise within accomplished week. Deliver service according with business specification. Support phase: Give assessment with any Change Request, if exists. Bug fixing. Technology and/or Methodology that were deployed: Microsoft Word, Microsoft Project, Microsoft Excel, C++, J2EE, Oracle Database, MySQL Database, SQL Developer, Toad for MySQL, Apache Tomcat, Oracle Weblogic, Oracle SOA Suite. \",\"occupation\":{\"jobTitle\":\"Technical Consultant\",\"jobTitleNormalized\":\"Technical Consultant\",\"classification\":{\"socCode\":2139,\"title\":\"Information technology professionals n.e.c.\",\"minorGroup\":\"Information Technology Professionals\",\"subMajorGroup\":\"SCIENCE, RESEARCH, ENGINEERING AND TECHNOLOGY PROFESSIONALS\",\"majorGroup\":\"PROFESSIONAL OCCUPATIONS\"},\"managementLevel\":\"Low\"}}]','[{\"id\":234028093,\"emsiId\":\"KS1200365FTR9X0M96T9\",\"name\":\"Microsoft Word\",\"lastUsed\":\"2021-03-01\",\"numberOfMonths\":122,\"type\":\"soft_skill\",\"sources\":[{\"section\":\"WorkExperience\",\"position\":1,\"workExperienceId\":39693488},{\"section\":\"WorkExperience\",\"position\":2,\"workExperienceId\":39693489},{\"section\":\"WorkExperience\",\"position\":3,\"workExperienceId\":39693490}]},{\"id\":234028094,\"emsiId\":\"KS123KG6DL8N3D5ZW036\",\"name\":\"Java Platform Enterprise Edition (J2EE)\",\"lastUsed\":\"2021-03-01\",\"numberOfMonths\":122,\"type\":\"hard_skill\",\"sources\":[{\"section\":\"WorkExperience\",\"position\":1,\"workExperienceId\":39693488},{\"section\":\"WorkExperience\",\"position\":2,\"workExperienceId\":39693489},{\"section\":\"WorkExperience\",\"position\":3,\"workExperienceId\":39693490}]},{\"id\":234028104,\"emsiId\":\"KS441Q56Y88HLXDMHM4Y\",\"name\":\"Vaadin\",\"lastUsed\":\"2023-05-15\",\"numberOfMonths\":23,\"type\":\"hard_skill\",\"sources\":[{\"section\":\"WorkExperience\",\"position\":0,\"workExperienceId\":39693487}]},{\"id\":234028105,\"emsiId\":\"KS440W865GC4VRBW6LJP\",\"name\":\"SQL (Programming Language)\",\"lastUsed\":\"2021-03-01\",\"numberOfMonths\":122,\"type\":\"hard_skill\",\"sources\":[{\"section\":\"Training/Certifications\"},{\"section\":\"WorkExperience\",\"position\":1,\"workExperienceId\":3